Implemented a date-independent `clock` class with:

- Construction from hour and minute values
- Minute addition and subtraction
- Wraparound across midnight
- Equality comparison for equivalent times

clock.h
```
#if !defined(CLOCK_H)
#define CLOCK_H

namespace date_independent {

class clock {
public:
    clock(int hour, int minute);

    clock add(int minutes) const;
    clock subtract(int minutes) const;

    bool operator==(const clock& other) const;

private:
    int minutes_since_midnight;
};

}  // namespace date_independent

#endif  // CLOCK_H
```

clock.cpp
```
#include "clock.h"

namespace date_independent {

namespace {
constexpr int minutes_per_day = 24 * 60;

int normalize_minutes(int minutes)
{
    minutes %= minutes_per_day;
    if (minutes < 0) {
        minutes += minutes_per_day;
    }
    return minutes;
}
}  // namespace

clock::clock(int hour, int minute)
    : minutes_since_midnight(normalize_minutes(hour * 60 + minute))
{
}

clock clock::add(int minutes) const
{
    return clock(0, normalize_minutes(minutes_since_midnight + minutes));
}

clock clock::subtract(int minutes) const
{
    return clock(0, normalize_minutes(minutes_since_midnight - minutes));
}

bool clock::operator==(const clock& other) const
{
    return minutes_since_midnight == other.minutes_since_midnight;
}

}  // namespace date_independent
